        self.stack1 = []
        self.stack2 = []

    def enqueue(self, data):
        self.stack1.append(data)

    def dequeue(self):
        if len(self.stack2) == 0:
            if len(self.stack1) == 0:
                return None
            while len(self.stack1) > 0:
                temp = self.stack1.pop()
                self.stack2.append(temp)
        return self.stack2.pop()

#include <stdio.h>

int main() 
{ 
    int arr1[] = {1, 2, 3, 4, 5}; 
    int arr2[] = {4, 5, 6, 7, 8}; 
    int i, j; 

    // Printing elements of first array 
    printf("Array 1: "); 
    for (i = 0; i < 5; i++) 
        printf("%d ", arr1[i]); 
    printf("\n"); 

    // Printing elements of second array 
    printf("Array 2: "); 
    for (i = 0; i < 5; i++) 
        printf("%d ", arr2[i]); 
    printf("\n"); 

    // Finding common elements 
    printf("Common elements: "); 
    for (i = 0; i < 5; i++) { 
        for (j = 0; j < 5; j++) { 
            if (arr1[i] == arr2[j]) 
                printf("%d ", arr1[i]); 
        } 
    } 

    return 0; 
} 

Sample Output:
Array 1: 1 2 3 4 5 
Array 2: 4 5 6 7 8 
Common elements: 4 5
